<div class="no-print"><div class="d-flex flex-wrap justify-content-between gap-2 mb-3"><div><h2>Exam Paper Generator</h2><p class="text-muted">Uses Exam Questions only. All counts, marks and quotas must be satisfied; no incomplete papers or silent mark changes.</p></div><a class="btn btn-outline-primary align-self-start" href="<?= APP_URL ?>/modules/learning/exam_specification_grids.php?<?= http_build_query(['class_id'=>$class,'subject_id'=>$subject]) ?>">Manage Exam Grids</a></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= sanitize($error) ?></div><?php endif; ?><?php examSelectorForm($classes,$subjectsByClass,$class,$subject); ?>
<?php if($subject): ?><form method="post"><input type="hidden" name="action" value="generate"><input type="hidden" name="class_id" value="<?= $class ?>"><input type="hidden" name="subject_id" value="<?= $subject ?>"><div class="row g-3 mb-3"><div class="col-md-6"><label class="form-label">Paper title</label><input class="form-control" name="exam_title" maxlength="200" required value="<?= sanitize($title) ?>"></div><div class="col-md-6"><label class="form-label">Link existing exam (optional)</label><select class="form-select" name="exam_id"><option value="">Standalone exam paper</option><?php foreach($exams as $e): ?><option value="<?= $e['id'] ?>" <?= (int)($_POST['exam_id']??0)===(int)$e['id']?'selected':'' ?>><?= sanitize($e['name']) ?></option><?php endforeach; ?></select></div></div><?php include __DIR__.'/../../includes/exam_grid_editor.php'; ?><button class="btn btn-success mb-4">Generate complete Exam Paper</button></form><?php endif; ?>
</div>
<?php if($paper): $mcqs=array_values(array_filter($paper['questions'],static fn($q)=>$q['type']==='MCQ'));$serial=$mcqs?2:1; ?>
<div class="alert alert-success no-print" role="status">Exam paper generated successfully: <?= count($paper['questions']) ?> question items, <?= learningDecimalString($paper['total_units']) ?> marks. Required question time: <?= learningDecimalString($paper['required_units']) ?> minutes.</div>
<div class="no-print d-flex flex-wrap gap-2 mb-3"><button type="button" class="btn btn-primary" onclick="printExamPaper(false)">Print Exam Paper</button><button type="button" class="btn btn-outline-primary" onclick="printExamPaper(true)">Print Answer Key</button></div>
<section id="examQuestionSheet" class="exam-paper card card-body mb-4"><header class="exam-print-header">
<?php if(!empty($school['logo'])): ?><img class="exam-print-logo" src="<?= sanitize(APP_URL.'/uploads/logo/'.rawurlencode(basename($school['logo']))) ?>" alt="School logo"><?php endif; ?>
<div><h2><?= sanitize($school['name_en']??'School Examination') ?></h2><p><?= sanitize($school['address']??'') ?></p><h3><?= sanitize($title) ?></h3></div></header>
<div class="exam-print-metadata"><span><?= sanitize($className) ?> — <?= sanitize($subjectName) ?></span><span>Full marks: <?= learningDecimalString($paper['total_units']) ?></span><span>Time: <?= sanitize($paper['grid']['duration_minutes']) ?> minutes</span><?php if($selectedExam): ?><span>Exam date: <?= sanitize(schoolDateLabel($selectedExam['start_date'],'BS','ymd')) ?></span><?php endif; ?></div><p class="exam-instructions">Attempt all questions. Figures in the margin indicate full marks.</p>
<?php if($mcqs): ?><h4 class="exam-section-title">1. Multiple-choice questions <span>[<?= learningDecimalString(array_sum(array_column($mcqs,'marks_units'))) ?>]</span></h4><?php foreach($mcqs as $i=>$q): ?><div class="exam-question"><div class="exam-question-heading"><strong>(<?= $i+1 ?>)</strong><div><?= safeRichHtml($q['question_text']) ?><div class="font-nepali"><?= safeRichHtml($q['question_text_np']??'') ?></div></div><span>[<?= learningDecimalString($q['marks_units']) ?>]</span></div><div class="exam-mcq-options"><?php $en=json_decode($q['options'],true);$np=json_decode($q['options_np'],true);foreach(['A','B','C','D'] as $o): ?><div><strong><?= strtolower($o) ?>.</strong> <?= safeRichHtml($en[$o]??'') ?><span class="font-nepali"><?= safeRichHtml($np[$o]??'') ?></span></div><?php endforeach; ?></div></div><?php endforeach; endif; ?>
<?php foreach($paper['rows'] as $r): if($r['type']==='MCQ')continue; ?><h4 class="exam-section-title"><?= sanitize($r['name']) ?> <span>[<?= sanitize($r['total_marks']) ?>]</span></h4><?php foreach($r['questions'] as $q): ?><div class="exam-question"><div class="exam-question-heading"><strong><?= $serial++ ?>.</strong><div><?= safeRichHtml($q['question_text']) ?><div class="font-nepali"><?= safeRichHtml($q['question_text_np']??'') ?></div></div><span>[<?= learningDecimalString($q['marks_units']) ?>]</span></div></div><?php endforeach; endforeach; ?>
</section>
<section id="examAnswersSheet" class="exam-paper card card-body mb-4"><h2>Answer Key — <?= sanitize($title) ?></h2><p><?= sanitize($className.' — '.$subjectName) ?></p><?php if($mcqs): ?><h3>1. MCQ answers</h3><ol><?php foreach($mcqs as $q): ?><li><strong><?= sanitize($q['correct_option']) ?></strong> <?= safeRichHtml($q['answer']??'') ?><div class="font-nepali"><?= safeRichHtml($q['answer_np']??'') ?></div></li><?php endforeach; ?></ol><?php endif; ?><?php $serial=$mcqs?2:1;foreach($paper['rows'] as $r): if($r['type']==='MCQ')continue;foreach($r['questions'] as $q): ?><article class="exam-question"><h3><?= $serial++ ?>. [<?= learningDecimalString($q['marks_units']) ?>]</h3><?php if(!questionImportHasContent($q['answer']??'')&&!questionImportHasContent($q['answer_np']??'')): ?><p class="text-muted">No model answer supplied; prepare the marking guide before assessment.</p><?php else: ?><?= safeRichHtml($q['answer']??'') ?><div class="font-nepali"><?= safeRichHtml($q['answer_np']??'') ?></div><?php endif; ?></article><?php endforeach;endforeach; ?></section>
<details class="no-print card card-body"><summary>Allocation audit</summary><p>Questions retain their stored marks. Estimated times are planning data, not official marking rules.</p><div class="table-responsive"><table class="table"><thead><tr><th>Chapter</th><th>Questions</th><th>Marks</th></tr></thead><tbody><?php foreach($paper['chapter_counts'] as $ch=>$n): ?><tr><td><?= sanitize($ch) ?></td><td><?= $n ?></td><td><?= learningDecimalString($paper['chapter_units'][$ch]??0) ?></td></tr><?php endforeach; ?></tbody></table></div></details>
